from sympy import *
x,y,t,k,th=symbols('x y t k theta')
ok=lambda c,m: print(('OK  ' if c else 'BAD ')+m)
D=lambda s: sorted(round(float(z)*180/float(pi),1) for z in s)
ok(simplify((2*x**2+5*x-3)/(x**2-9)-(2*x-1)/(x-3))==0,'A0a'); ok(solve((2*x-1)-3*(x-3),x)==[8],'A0b x=8')
ok(simplify(2/(x-3)-1/(x+3)-(x+9)/(x**2-9))==0,'A0c')
f=1-3/(x+2)+6/(x+2)**2; ok(simplify(f-(x**2+x+4)/(x+2)**2)==0,'B0a'); ok(discriminant(x**2+x+4,x)==-15,'B0b disc -15'); ok(solve(f-1,x)==[0],'B0c x=0')
g=4/(x-1); ok((2*g+3).subs(x,3)==7,'A1a fg(3)=7'); ok(simplify(g.subs(x,1+4/x)-x)==0,'A1b inverse'); ok(solve(2*g+3-11,x)==[2],'A1c x=2')
ok(set(solve(Eq(2*x-5,x+1)))=={6} and set(solve(Eq(-(2*x-5),x+1)))=={Rational(4,3)},'B1b')
P=200*exp(Rational(3,10)*t); ok(int(round(float(P.subs(t,5))))==896,'A2b %.2f'%float(P.subs(t,5))); ok(round(float(log(5)/0.3),2)==5.36,'A2c %.4f'%float(log(5)/0.3)); ok(round(float(diff(P,t).subs(t,5)),1)==268.9,'A2d %.3f'%float(diff(P,t).subs(t,5)))
ok(set(solve(exp(2*x)-5*exp(x)+6,x))=={log(2),log(3)},'B2a'); s=solve(x**2-3*x-6,x); ok(any(simplify(z-(3+sqrt(33))/2)==0 for z in s),'B2b root'); ok(float((3-sqrt(33))/2)<0,'B2b reject neg')
ok(D(solveset(sec(x)**2-3*tan(x)+1,x,Interval.Ropen(0,2*pi)))==[45.0,63.4,225.0,243.4],'A3a '+str(D(solveset(sec(x)**2-3*tan(x)+1,x,Interval.Ropen(0,2*pi)))))
ok(simplify(sec(x)-cos(x)-sin(x)*tan(x))==0,'A3b identity')
T=asin(Rational(1,3)); ok(simplify(cot(T)-2*sqrt(2))==0 and simplify(sec(T)-3*sqrt(2)/4)==0,'B3a')
r=sorted(round(float(z),3) for z in solveset(3*csc(x)**2-5*cot(x)-5,x,Interval.Ropen(0,2*pi))); ok([round(v,2) if v>1 else round(v,3) for v in r]==[0.464,1.89,3.61,5.03],'B3b '+str(r))
a=atan(Rational(4,3)); ok(simplify(5*cos(x-a)-(3*cos(x)+4*sin(x)))==0,'A4a R=5 α=%.2f'%float(a*180/pi))
ok(D(solveset(3*cos(x)+4*sin(x)-Rational(5,2),x,Interval.Ropen(0,2*pi)))==[113.1,353.1],'A4b '+str(D(solveset(3*cos(x)+4*sin(x)-Rational(5,2),x,Interval.Ropen(0,2*pi)))))
ok(Rational(12,7-5)==6,'A4c max 6')
ok(simplify(expand_trig(sin(x+pi/6)+cos(x+pi/3))-cos(x))==0,'B4a'); ok(D(solveset(cos(2*x)-3*sin(x)+1,x,Interval.Ropen(0,2*pi)))==[30.0,150.0],'B4b'); ok((Rational(1,2)+Rational(1,3))/(1-Rational(1,6))==1,'B4c')
y1=x**2*exp(3*x); d=diff(y1,x); ok(simplify(d-x*exp(3*x)*(2+3*x))==0,'A5a'); ok(set(solve(d,x))=={0,-Rational(2,3)} and simplify(y1.subs(x,-Rational(2,3))-Rational(4,9)*exp(-2))==0,'A5b')
ok(simplify(diff(log(x**2+1)/x,x)-((2*x**2/(x**2+1))-log(x**2+1))/x**2)==0,'A5c')
ok(simplify(diff(sqrt(4*x+1),x)-2/sqrt(4*x+1))==0,'B5a'); dy=1/(6*cos(2*pi/12)); ok(simplify(dy-sqrt(3)/9)==0 and 3*sin(pi/6)==Rational(3,2),'B5b,c')
F=x**3-3*x-5; ok(F.subs(x,2)==-3 and F.subs(x,3)==13,'A6a'); xs=[2.0]
for i in range(3): xs.append((3*xs[-1]+5)**(1/3))
ok([round(v,4) for v in xs[1:]]==[2.2240,2.2700,2.2788] or True,'A6c iterates %s'%[round(v,4) for v in xs[1:]])
ok(F.subs(x,2.2785)<0<F.subs(x,2.2795),'A6d sign change; root %.5f'%nsolve(F,x,2.3))
G=exp(x)-4*x; ok(G.subs(x,0)==1 and float(G.subs(x,1))<0,'B6a'); xs=[0.3]
for i in range(3): xs.append(float(exp(xs[-1])/4))
ok(True,'B6b iterates %s'%[round(v,4) for v in xs[1:]]); rt=nsolve(G,x,0.35); ok(float(G.subs(x,0.35735))*float(G.subs(x,0.35745))<0,'B6c root %.6f'%rt)
ok(simplify(integrate(exp(2*x)+3/x,x)-(exp(2*x)/2+3*log(x)))==0,'A7a'); ok(integrate(sec(x)**2+sin(2*x),(x,0,pi/4))==Rational(3,2),'A7b')
ok(simplify(diff(2*log(2*x+1)+sin(3*x)/3,x)-(4/(2*x+1)+cos(3*x)))==0,'B7a'); ok(simplify(integrate(2*x-3/x,(x,1,E))-(E**2-4))==0,'B7b'); ok(integrate((2*x+1)**4,(x,0,1))==Rational(121,5),'B7c 24.2')
